#!/usr/bin/env python3
"""Patch the Windows runner generated by `flutter create --platforms=windows`.

- flutter_local_notifications_windows still includes <experimental/coroutine>,
  refused by recent MSVC (error STL1011) unless the deprecation is silenced:
  the definition is set for every target, plugins included.

Idempotent, and fails loudly if the template changed shape.
"""
import re
import sys
from pathlib import Path

CMAKE = Path("windows/CMakeLists.txt")
LINE = "add_compile_definitions(_SILENCE_EXPERIMENTAL_COROUTINE_DEPRECATION_WARNINGS)"


def main() -> int:
    if not CMAKE.exists():
        print(f"error: {CMAKE} not found, run flutter create first", file=sys.stderr)
        return 1
    text = CMAKE.read_text(encoding="utf-8")
    if LINE not in text:
        text, n = re.subn(r"(project\([^)]*\)\s*\n)", r"\1" + LINE + "\n", text, count=1)
        if n != 1:
            print("error: project() not found in windows/CMakeLists.txt", file=sys.stderr)
            return 1
        CMAKE.write_text(text, encoding="utf-8")
    print(f"patched {CMAKE}")
    # Window title and file properties « SARCADE », not the package name
    # « sarcade_app » (card « Client Windows : écran gris », 31 Oct 2026,
    # point 4). The exe keeps its name (installer, shortcuts, updates).
    main_cpp = Path("windows/runner/main.cpp")
    text = main_cpp.read_text(encoding="utf-8")
    if 'L"SARCADE"' not in text:
        text, n = re.subn(r'window\.Create\(L"[^"]*"', 'window.Create(L"SARCADE"', text, count=1)
        if n != 1:
            print("error: window.Create not found in windows/runner/main.cpp", file=sys.stderr)
            return 1
        main_cpp.write_text(text, encoding="utf-8")
    print(f"patched {main_cpp}")
    rc = Path("windows/runner/Runner.rc")
    text = rc.read_text(encoding="utf-8")
    for key in ("FileDescription", "ProductName"):
        text = re.sub(r'(VALUE "%s", )"[^"]*"' % key, r'\1"SARCADE"', text)
    rc.write_text(text, encoding="utf-8")
    print(f"patched {rc}")
    # SARCADE icon (assets/icon/generated, tool/make_app_icons.py).
    ico = Path("windows/runner/resources/app_icon.ico")
    ico.write_bytes(Path("assets/icon/generated/windows/app_icon.ico").read_bytes())
    print(f"patched {ico}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
